// buff_value.rs:17~53. 반환 = (die_imminent, cc_ready)

tps  = *(*(*(data+0x08) + 0x08) + 0x12F8)          // :19
game = *(data+0x00)                                // &AbstractGameWithCache(8840B)
bump = *(*(data+0x08) + 0x00)                      // bumpalo Bump

// --- (1) 근처 적 수집 : 21~26 ---
enemy = 1 - player[0x930]
if enemy >= 2 { panic_bounds_check(enemy, 2) }     // 팀은 2개뿐
slots5 = &game[0x1E0][enemy]                       // [Option<&Entity>; 5]
near_enemies: Vec<&Entity, bump> =
  slots5.iter().filter_map(AbstractGameWithCache::iter_champions#0)   // None 슬롯 제거
        .filter(defensive_crisis#0)                                  // 아래 클로저
        .collect_in(bump)

// filter 클로저 defensive_crisis#0 (본문은 이 줄범위 밖 — m10.ll:55868 call_mut 심에서 읽음)
//   :23  mr = plan_legacy::old::battle::max_range(e, target)
//   :24  if e.distance_sq(target) > (mr + 30000)^2  -> false   // dx,dy 는 abs_diff 후 제곱합
//   :25  if fight_model::is_ignored_well_enemy(version, player, e) -> false
//          (내부: e.team_type tag==0 && e.team==1-player.team 이면
//           path_finder::is_enemy_well_danger(version, player, e.x, e.y) 를 보고 true)
//   :26  else blackboard[1-player.team].is_recent_visible(game.f0, game.f8, player, e)
//   => 남는 것 = 사거리+30000 안 + 우물 무시대상 아님 + 최근에 본 적

// --- (2) 죽음 임박 : 30~35 ---
die_imminent = false                                          // :30
if near_enemies.len() == 0 { return (false, false) }          // 적이 없으면 두 값 모두 false
tp = game.player_by_champion_id(target[0x5C0])                // :32
if tp != null {
  die = fight_check::check_kill_die_tick(version, rnd, data, tp, target,
                                         near_enemies.clone(),
                                         Vec::new_in(bump),   // :34 빈 Vec
                                         debug)               // :33  (invoke)
  die_imminent = die < tps * 2                                // :35
  if near_enemies.len() == 0 { return (die_imminent, false) }
}

// --- (3) 적 CC 즉시 가능 여부 : 41~48 ---
cc_ready = false
for e in near_enemies {                                       // :41
  is_champ = (e[0x68] == 13)
  lv       = e[0x5C8]
  slots = [ (&e[0x4C8],                   is_champ ? e[0xB8] : 0),   // :43 skill1
            (lv > 2 ? &e[0x500] : &NONE,  is_champ ? e[0xC0] : 0),   // :44 skill2
            (lv > 4 ? &e[0x538] : &NONE,  is_champ ? e[0xC8] : 0) ]  // :45 ult
  if slots.iter().any(|(eff, cd)| {                            // :47
       cd <= tps                                               //   남은 쿨타임이 tps(=1초) 이하
       && eff.discr != -1                                      //   :48 Option<Effect>.as_ref() 가 Some
       && fight_check::effect_cc_time(version, eff).is_some()  //   :48 그 효과가 CC 지속시간을 가짐 (invoke)
     })
  { cc_ready = true; break }                                   // 첫 히트에서 즉시 반환
}
return (die_imminent, cc_ready)                                // :53

// 주의 1: 세 슬롯 검사는 IR 에서 완전히 펼쳐져 있고 순서는 skill1 -> skill2 -> ult 로 고정.
// 주의 2: 쿨타임 비교가 효과 검사보다 먼저라 cd > tps 인 슬롯은 effect_cc_time 을 아예 부르지 않는다.
// 주의 3: kind!=13 이면 쿨타임 3종이 전부 0 으로 취급되어 cd<=tps 를 항상 통과한다(비챔피언 엔티티는
//         효과 유무만으로 CC 위협으로 잡힌다).
